// PlanBPerf V2: exact micro-primitives (WaterProximityBits, DynamicShuffleList, TextureWidthCache). Origin: work/astra-managed, reworked for the plugin.
using System.Collections.Generic;
using UnityEngine;

namespace PlanBPerf.V2
{
    public static class ExactPrimitives
    {
        // Replaces GHexes.GetWaterProximity(int2). Reverses flag bits 12..15 into weights 8,4,2,1.
        // GHexes.HasFlag is the game's own bit test (no System.Enum.HasFlag boxing), so one read of the flag word is enough.
        public static int WaterProximity(int2 coords)
        {
            uint f = (uint)GHexes.flags[coords.x, coords.y];
            return (int)(((f >> 9) & 8u) | ((f >> 11) & 4u) | ((f >> 13) & 2u) | ((f >> 15) & 1u));
        }

        // Replaces only the Shuffle<int2> call in SItems.Update01s_DynamicItems: same n RNG draws (including the last i=n-1), same swap order.
        public static void DynamicShuffle(IList<int2> source)
        {
            var list = source as List<int2>;
            if (list == null) { SMisc.Shuffle(source); return; }
            for (int i = 0; i < list.Count; i++)
            {
                int2 value = list[i];
                int index = UnityEngine.Random.Range(i, list.Count);
                list[i] = list[index];
                list[index] = value;
            }
        }
    }

    // TextureInfos.GetPixelIdx(x, y) = y * tx.width + (x + size) % size. tx.width is a Unity icall on every pixel.
    // The game never resizes or reinitialises TextureInfos.tx (audit: no Reinitialize/Resize/LoadRawTextureData). The cache keeps the ACTUAL width
    // (a normal-map clone can differ from size) keyed​ by (info, tx reference): a replaced texture object misses and re-reads the width.
    // Four lock-free slots of immutable entries (4 TextureInfos instances exist, two per pixel type); reference writes are atomic, so the snow
    // callbacks coming from the native worker threads can race on it without tearing (worst case: a redundant tx.width read).
    public static class TextureIndex<T> where T : struct
    {
        private sealed class Entry
        {
            public readonly SViewWorld.TextureInfos<T> Info;
            public readonly Texture2D Tex;
            public readonly int Width;
            public Entry(SViewWorld.TextureInfos<T> info, Texture2D tex, int width) { Info = info; Tex = tex; Width = width; }
        }

        private static Entry _e0, _e1, _e2, _e3;
        private static int _next;
        public static int Misses;

        public static void Forget(SViewWorld.TextureInfos<T> info)
        {
            if (_e0 != null && ReferenceEquals(_e0.Info, info)) _e0 = null;
            if (_e1 != null && ReferenceEquals(_e1.Info, info)) _e1 = null;
            if (_e2 != null && ReferenceEquals(_e2.Info, info)) _e2 = null;
            if (_e3 != null && ReferenceEquals(_e3.Info, info)) _e3 = null;
        }

        public static void ForgetAll() { _e0 = _e1 = _e2 = _e3 = null; }

        private static int Width(SViewWorld.TextureInfos<T> info, Texture2D tx)
        {
            Entry e;
            if ((e = _e0) != null && ReferenceEquals(e.Info, info) && ReferenceEquals(e.Tex, tx)) return e.Width;
            if ((e = _e1) != null && ReferenceEquals(e.Info, info) && ReferenceEquals(e.Tex, tx)) return e.Width;
            if ((e = _e2) != null && ReferenceEquals(e.Info, info) && ReferenceEquals(e.Tex, tx)) return e.Width;
            if ((e = _e3) != null && ReferenceEquals(e.Info, info) && ReferenceEquals(e.Tex, tx)) return e.Width;
            Misses++;
            int w = tx.width;   // null tx throws here, exactly like the original
            var n = new Entry(info, tx, w);
            switch ((_next++) & 3)
            {
                case 0: _e0 = n; break;
                case 1: _e1 = n; break;
                case 2: _e2 = n; break;
                default: _e3 = n; break;
            }
            return w;
        }

        public static int Run(SViewWorld.TextureInfos<T> info, int x, int y)
        {
            return y * Width(info, info.tx) + (x + info.size) % info.size;
        }
    }
}
