    internal static class V2Util
    {
        internal static void CheckIl(MethodBase m, string key)
        {
            if (Sig.SkipIlCheck) return;
            string expected;
            if (!ExpectedIl.Hash.TryGetValue(key, out expected)) throw new SkipException("no expected IL hash for " + key​);
            if (Sig.IlHash(m) != expected) throw new SkipException("IL changed (game update?) " + key);
        }

        internal static MethodInfo SingleGeneric(Type t, string name, int paramCount)
        {
            var found = t.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance)
                .Where(x => x.Name == name && x.IsGenericMethodDefinition && x.GetParameters().Length == paramCount).ToList();
            if (found.Count != 1) throw new SkipException(t.Name + "." + name + " generic overload count " + found.Count);
            return found[0];
        }

        internal static int CountCalls(MethodBase m, Func<MethodInfo, bool> pred)
        {
            int n = 0;
            foreach (var ci in PatchProcessor.GetOriginalInstructions(m))
            {
                var mi = ci.operand as MethodInfo;
                if ((ci.opcode == OpCodes.Call || ci.opcode == OpCodes.Callvirt) && mi != null && pred(mi)) n++;
            }
            return n;
        }
    }

